"""Build the report from saved artifacts, without fitting or selecting models."""
from pathlib import Path
import json
import html
import pandas as pd
import numpy as np

ROOT=Path(__file__).resolve().parents[1]
A=ROOT/'reports/artifacts'

def table(frame,precision=4):
    return frame.to_html(index=False,float_format=lambda x:f'{x:.{precision}f}',border=0)

def main():
    audit=json.loads((A/'audit.json').read_text());stats=json.loads((A/'training_analysis.json').read_text());selection=json.loads((A/'selection.json').read_text())
    folds=pd.read_csv(A/'validation_folds.csv');records=pd.read_csv(A/'validation_predictions.csv');test=pd.read_csv(A/'holdout_metrics.csv')
    seg=pd.read_csv(A/'segments.csv');cores=pd.read_csv(A/'core_segments.csv')
    cpu=folds[folds.target=='aggregate_cpu_utilization'];summary=cpu.groupby('model')[['mae','rmse']].mean().sort_values('mae').reset_index()
    baseline=float(summary.loc[summary.model=='last','mae'].iloc[0]);summary['MAE improvement %']=100*(1-summary.mae/baseline)
    selected=selection['selected']['aggregate_cpu_utilization'];v=float(summary.loc[summary.model==selected,'mae'].iloc[0])
    h=test[(test.target=='aggregate_cpu_utilization')&(test.model=='selected')].iloc[0];b=test[(test.target=='aggregate_cpu_utilization')&(test.model=='last_baseline')].iloc[0]
    improvement=100*(1-h.mae/b.mae)
    rc=records[(records.target=='aggregate_cpu_utilization')&(records.model==selected)]
    peaks=rc.actual>=rc.peak_threshold
    peakmae=float(np.abs(rc.loc[peaks,'actual']-rc.loc[peaks,'prediction']).mean())
    step=rc.assign(ae=np.abs(rc.actual-rc.prediction)).groupby('step').ae.mean()
    prediction=pd.read_csv(ROOT/'predictions.csv')
    margin=selection['one_sided_residual_p95_margin']['aggregate_cpu_utilization']
    pages=[]
    pages.append(('Executive summary and data contract',f'''
<p class="byline">Prince Maurya · Atomity AI/ML take-home · fixed data-v1 release</p>
<p>For this selected Azure VM population, a small regularized autoregression improves two-hour average-CPU forecasting over last-value persistence. Training-only rolling validation selected ridge AR(6); its final holdout MAE is <b>{h.mae:.4f} percentage points</b>, compared with {b.mae:.4f} for persistence ({improvement:.2f}% lower). Holdout RMSE is {h.rmse:.4f} versus {b.rmse:.4f}. These are aggregate utilization errors, not percentages of total physical cloud capacity.</p>
<p>The active-VM target is exactly 10,000 throughout. Persistence forecasts it without error. This is mostly a consequence of complete-trace dataset selection, not evidence of predicting real fleet churn. CPU forecasting is the informative part of this experiment.</p>
<h2>Inputs and audit</h2>
<p>The exact data-v1 release contains {audit['rows']:,} readings for {audit['vms']:,} VMs and {audit['timestamps']} five-minute timestamps. Source seconds run from 0 to 39,900, a first-to-last span of 11.083 hours. There are no missing fields, duplicate VM/timestamp pairs, invalid CPU averages, min/average/max inconsistencies, or missing grid readings. Metadata has one row per VM. All three release SHA-256 checks pass.</p>
<p>At timestamp t, active count is the number of distinct VMs with a finite average CPU in [0,100]. Aggregate CPU is the unweighted mean of these valid VM averages. Invalid readings would be excluded from both targets; duplicates and entirely missing timestamps cause a clear error instead of silent repair. Each VM has exactly 134 valid readings in the supplied release, so no imputation or resampling is needed.</p>
<h2>Information boundary</h2>
<p>Observations 1–110 (seconds 0–32,700) are training. Observations 111–134 (33,000–39,900) are a fixed 24-step test. Full targets are constructed first, but only the training prefix enters modeling, selection and workload summaries. Test values enter the evaluation function only after selection is saved and predictions written. Timestamps are source-relative seconds; mapping them to a real date, weekday or time zone would be unsupported.</p>
<h2>Sources</h2>
<p class="small">Contracts: github.com/atomityhq/forecasting-challenge (ASSIGNMENT.md, DATASET.md, SUBMISSION.md). Data provenance: release data-v1/DATA_CARD.md, derived from Microsoft Azure Public Dataset V2. Upstream starter revision: 6e5ac0e4d2f1d81fab0903ce0a974037745db35b. All numerical findings in this report come from reports/artifacts, generated by the supplied implementation.</p>
'''))
    pages.append(('Workload analysis: stable means can hide busy VMs',f'''
<p>Training aggregate CPU averages {stats['aggregate_cpu_mean']:.3f}% with temporal standard deviation {stats['aggregate_cpu_std']:.3f} percentage points, and ranges from {stats['aggregate_cpu_min']:.3f}% to {stats['aggregate_cpu_max']:.3f}%. Lag-one autocorrelation is {stats['aggregate_lag1_autocorrelation']:.3f}, supporting a small short-memory candidate, but not establishing long-term periodicity.</p>
<img src="artifacts/figures/workload.png" alt="Training VM CPU distribution and category means">
<p>The median VM reading is {stats['cpu_quantiles']['0.5']:.2f}%, while the 99th percentile is {stats['cpu_quantiles']['0.99']:.2f}%; {100*stats['over_80_cpu_fraction']:.2f}% of training readings exceed 80%. Low fleet-average utilization therefore does not imply every VM has spare capacity. Per-VM scheduling and interactive-service protections remain necessary.</p>
{table(seg[['vm_category','vms','mean_cpu','p95_cpu','vm_share']])}
<p>Interactive VMs are 30.91% of the population but contribute about 37.78% of the summed unweighted average-CPU readings; their mean CPU is higher than the delay-insensitive segment. This is not a share of core-seconds because VM capacities differ. Category metadata may summarize a broader source history: it is used only for retrospective explanation, never as a forecast feature.</p>
<p>Core buckets also differ: the 2-core bucket contains 7,534 VMs and averages 9.764% CPU; the 4-core bucket contains 1,908 and averages 7.919%. The &gt;24 bucket has only ten VMs, making its 6.619% average fragile. Bucket labels are not exact core counts, so no fabricated core-weighted demand conversion is attempted.</p>
<h2>Lifetimes and selection bias</h2>
<p>Observed additions and departures in training are both zero. Creation metadata equals source-second zero for every selected VM; deletion metadata ranges from 40,500 to 2,591,400, beyond this observation window. These fields do not provide a forecast-time churn signal and are excluded from modeling. Eligibility required complete traces, suppressing churn and survivorship failures by construction. Findings apply to the curated population, not the whole Azure fleet.</p>
'''))
    pages.append(('Forecasting method and time-aware validation',f'''
<p>Eight fixed candidates are compared on each target using identical expanding origins: fit 1–38/predict 39–62; fit 1–62/predict 63–86; fit 1–86/predict 87–110. Each forecast is a complete two-hour path with no teacher forcing. Validation windows do not overlap, although expanding training windows and serially dependent observations mean the folds are not independent experiments.</p>
{table(summary)}
<p>CPU mean validation MAE for ridge AR is {v:.4f} versus {baseline:.4f} for persistence, a {100*(1-v/baseline):.2f}% improvement. Ridge does not win every fold: its MAEs are 0.1895, 0.1352 and 0.1882; persistence gives 0.1947, 0.2975 and 0.1324. The choice is based on the declared overall mean, not on selecting a favorable fold. Active-count models tie at zero; the simplest candidate, persistence, wins.</p>
<h2>Equations and parameters</h2>
<p>Persistence repeats the last value. Moving averages repeat the last 6/12/24-point mean. Exponential smoothing uses fixed alpha 0.2 or 0.5. The damped trend fits a slope to the last 12 observations and adds slope × sum(0.8^j), j=1…h. None of these settings is tuned on the final holdout.</p>
<p>Ridge AR uses the previous six target values in reverse chronological order, plus an intercept. At every fold it standardizes using that fold's training mean and population standard deviation only. It solves (XᵀX + 10D)β = Xᵀy with D's intercept entry zero, then forecasts recursively, adding its own predicted standardized values to history. On a constant/too-short history it falls back to persistence. Final fitting repeats this procedure on all 110 training observations.</p>
<h2>Leakage controls and model restraint</h2>
<p>No random shuffling, future lags, full-series normalization, source CPU summary features, deletion-time features, external data, or holdout-based tuning is used. All candidates receive the same output bounds. Calendar seasonality and high-capacity neural models are not justified by fewer than twelve hours of aggregate history. Model complexity is deliberately limited relative to sample size.</p>
<p>The candidate list, selected names, origins and input hashes are saved in selection.json before held-out evaluation. This documents the code's execution order, not a cryptographic proof of historical precommitment. A regression test changes all held-out labels and checks unchanged predictions and choices.</p>
'''))
    pages.append(('Held-out evaluation and failure analysis',f'''
{table(test[['target','model','mae','rmse','bias']])}
<img src="artifacts/figures/forecast.png" alt="Frozen forecast versus held-out actual values">
<p>CPU MAE relative to persistence is {h.mae/b.mae:.4f}; RMSE improves by {100*(1-h.rmse/b.rmse):.2f}%. Positive bias means overprediction: the selected forecast's average error is +{h.bias:.4f} percentage points, compared with {b.bias:+.4f} for persistence. Count MAE/RMSE are both zero. A relative count improvement is undefined because the baseline denominator is zero, not 100% improvement.</p>
<h2>Peaks and horizon effects</h2>
<p>Each validation fold defines a high-load threshold using only its fitting prefix's 90th CPU percentile. Across the selected model's 72 validation predictions, {int(peaks.sum())} are at or above that fold-specific threshold and their MAE is {peakmae:.4f} percentage points. Mean absolute error across lead times 1–6 is {step.loc[1:6].mean():.4f}, versus {step.loc[19:24].mean():.4f} for leads 19–24. These are small-sample diagnostics, not statistically established horizon laws.</p>
<p>The final training-derived threshold is {h.peak_threshold_training_p90:.4f}%. The holdout contains zero points at or above it. Consequently, final-test high-load performance is unmeasurable, not perfect; no peak MAE is invented. The largest held-out CPU underprediction is {h.max_underprediction:.4f} percentage points for ridge versus {b.max_underprediction:.4f} for persistence.</p>
<h2>Failure modes</h2>
<p>The ridge path can regress toward the recent training mean and miss abrupt rises. Its third validation fold is worse than persistence, demonstrating regime sensitivity. The final holdout is less extreme than training-defined peak conditions, so its better aggregate score is not evidence of safe forecasting through an unseen surge. The constant count target cannot assess new VM launches, departures or data outages. Aggregate averaging also hides localized hot spots and five-minute sampling hides within-interval bursts.</p>
'''))
    pages.append(('Operational recommendation, limits and reproducibility',f'''
<h2>A conservative advisory policy</h2>
<p>Refresh a two-hour CPU forecast every five minutes once enough history is available. Add <b>{margin:.4f} percentage points</b> to each forecast as a provisional one-sided headroom signal. This value is the empirical 95th percentile of actual-minus-predicted residuals from the selected model's 72 validation forecasts, floored at zero. It is not a calibrated 95% prediction interval: the same folds selected the model, residuals are dependent, and different horizons are pooled.</p>
<p>The issued CPU forecasts range from {prediction.aggregate_cpu_utilization.min():.4f}% to {prediction.aggregate_cpu_utilization.max():.4f}%; forecast-plus-buffer ranges from {prediction.aggregate_cpu_utilization.min()+margin:.4f}% to {prediction.aggregate_cpu_utilization.max()+margin:.4f}%. None of the 24 holdout CPU values exceeds that upper signal. This is retrospective diagnostic coverage on a single quiet window, not a future reliability guarantee.</p>
<p>Use a breach of an operator-defined, SLA-tested utilization budget as an alert to review headroom; do not treat the training 90th percentile as a physical saturation threshold. Require live per-VM CPU, latency, memory and scheduler constraints before scaling down. Protect interactive workloads first; delay-insensitive work may be deferred only under an actual service policy. A larger buffer reduces under-provisioning risk but increases reserved idle capacity; a smaller one saves capacity while increasing the chance of queues or latency spikes.</p>
<p>There is no defensible formula here for exact server count: required targets are unweighted VM percentages, VM sizes are bucketed, and neither physical placements nor SLA limits are supplied. Constant-count accuracy provides no basis for fleet-wide churn planning.</p>
<h2>Engineering and reproduction</h2>
<p>Run <code>python scripts/download_data.py</code> after installing the pinned dependencies, then <code>python -m pytest -q</code> and <code>python run.py --data challenge_data --output predictions.csv</code>. The prediction file has exactly 24 chronological rows with timestamp, active_vm_count, aggregate_cpu_utilization, no index, and finite bounded values. The command recreates audit, selection, per-fold predictions, final metrics and figures. Report generation is separate and reads saved results only.</p>
<p>Tests cover starter metrics/splits, constant candidates, bounds, duplicate/gap rejection, invalid-reading exclusion, checksum failures, output contract, held-out-label mutation, smaller input populations/horizons and the default plotting/evaluation path. Official checksummed mode enforces the fixed release contract; explicit smoke mode allows reviewer replacement data without hard-coded public timestamps or a hard-coded 10,000 prediction.</p>
<h2>Limitations and next work</h2>
<p>Three folds and one two-hour test cannot establish generalization. Obtain a longer trace with representative arrivals/departures, evaluate across days and segments, measure within-interval peaks, and calibrate uncertainty on genuinely separate windows. Investigate more complex models only after those data and evaluation gaps are fixed. Implementation and writing used AI-assistant support; all metrics were actually computed by the supplied code. No private data, external ML API or paid compute was used.</p>
'''))
    css='''@page {size:A4;margin:16mm 17mm;} *{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17212b;font-size:10pt;line-height:1.35;margin:0}section{break-after:page}section:last-child{break-after:auto}h1{font-size:19pt;line-height:1.15;color:#12384c;margin:0 0 10pt}h2{font-size:11pt;margin:12pt 0 4pt;color:#1d5563}p{margin:0 0 8pt}table{border-collapse:collapse;width:100%;font-size:8pt;margin:8pt 0}th,td{padding:4pt;border-bottom:1px solid #dbe1e6;text-align:left}th{background:#eef3f5}img{display:block;width:100%;max-height:65mm;object-fit:contain;margin:5pt 0}.byline,.small{font-size:8pt;color:#52616b}code{font-size:8pt}.page-number{font-size:8pt;color:#52616b;margin-bottom:6pt}'''
    document='<!doctype html><html><head><meta charset="utf-8"><title>Cloud workload forecasting — Prince Maurya</title><style>'+css+'</style></head><body>'
    markdown='# Cloud workload forecasting — Prince Maurya\n\n'
    for i,(title,body) in enumerate(pages,1):
        document+=f'<section><div class="page-number">ATOMITY · CLOUD WORKLOAD FORECASTING · {i}/5</div><h1>{html.escape(title)}</h1>{body}</section>'
        markdown+=f'\n## {i}. {title}\n\n'+body+'\n'
    document+='</body></html>'
    (ROOT/'reports/final_report.html').write_text(document,encoding='utf-8')
    (ROOT/'reports/final_report.md').write_text(markdown,encoding='utf-8')
    diagnostics={'validation_peak_points':int(peaks.sum()),'validation_peak_mae':peakmae,'validation_mean_mae':v,'baseline_validation_mean_mae':baseline,'holdout_mae_improvement_percent':improvement}
    (A/'report_diagnostics.json').write_text(json.dumps(diagnostics,indent=2))
    print(json.dumps(diagnostics,indent=2))

if __name__=='__main__':main()
